77	template <bool zero_init=false, typename Engine0, typename Layout0, typename Engine1, typename Layout1>
78	__forceinline__ __device__ void max_scale_exp2_sum(Tensor<Engine0, Layout0> &tensor, Tensor<Engine1, Layout1> &max, Tensor<Engine1, Layout1> &sum, const float scale) {
79	    static_assert(Layout0::rank == 2, "Only support 2D Tensor"); static_assert(Layout1::rank == 1, "Only support 1D Tensor"); CUTE_STATIC_ASSERT_V(size<0>(max) == size<0>(tensor));
80	    #pragma unroll
81	    for (int mi = 0; mi < size<0>(tensor); ++mi) {
82	        MaxOp<float> max_op;
83	        max(mi) = zero_init ? tensor(mi, 0) : max_op(max(mi), tensor(mi, 0));
84	        #pragma unroll
85	        for (int ni = 1; ni < size<1>(tensor); ni++) {
86	            max(mi) = max_op(max(mi), tensor(mi, ni));
87	        }
88	        max(mi) = Allreduce<4>::run(max(mi), max_op);
89	        // If max is -inf, then all elements must have been -inf (possibly due to masking).
90	        // We don't want (-inf - (-inf)) since that would give NaN.
91	        const float max_scaled = max(mi) == -INFINITY ? 0.f : max(mi) * scale;
92	        sum(mi) = 0;
93	        #pragma unroll
94	        for (int ni = 0; ni < size<1>(tensor); ++ni)  {
95	            // Instead of computing exp(x - max), we compute exp2(x * log_2(e) -
96	            // max * log_2(e)) This allows the compiler to use the ffma
97	            // instruction instead of fadd and fmul separately.
98	            tensor(mi, ni) = exp2f(tensor(mi, ni) * scale - max_scaled);
99	            sum(mi) += tensor(mi, ni);
100	        }
101	    }
102	}
