107	__forceinline__ __device__ void scale_apply_exp2(Tensor<Engine0, Layout0> &tensor, Tensor<Engine1, Layout1> const &max, const float scale) {
108	    constexpr static float max_offset = Use_max_offset ? 8.0f : 0.0f;
109	    static_assert(Layout0::rank == 2, "Only support 2D Tensor");
110	    static_assert(Layout1::rank == 1, "Only support 1D Tensor");
111	    CUTE_STATIC_ASSERT_V(size<0>(max) == size<0>(tensor));
112	    #pragma unroll
113	    for (int mi = 0; mi < size<0>(tensor); ++mi) {
114	        // If max is -inf, then all elements must have been -inf (possibly due to masking).
115	        // We don't want (-inf - (-inf)) since that would give NaN.
116	        // If we don't have float around M_LOG2E the multiplication is done in fp64.
117	        const float max_scaled = Check_inf
118	            ? (max(mi) == -INFINITY ? 0.f : (!Scale_max ? max(mi) : max(mi) * scale) - max_offset)
119	            : (!Scale_max ? max(mi) : max(mi) * scale) - max_offset;
120	        #pragma unroll
121	        for (int ni = 0; ni < size<1>(tensor); ++ni)  {
122	            // Instead of computing exp(x - max), we compute exp2(x * log_2(e) -
123	            // max * log_2(e)) This allows the compiler to use the ffma
124	            // instruction instead of fadd and fmul separately.
125	            tensor(mi, ni) = exp2f(tensor(mi, ni) * scale - max_scaled);
126	        }
127	    }
128	}
